{"linux":"// Place your key bindings in this file to override the defaults
[
    {
        "key": "ctrl+k ctrl+f",
        "command": "-editor.action.formatSelection",
        "when": "editorHasDocumentSelectionFormattingProvider && editorTextFocus && !editorReadonly"
    },
    {
        "key": "ctrl+k ctrl+f",
        "command": "editor.action.formatSelection.multiple"
    },
    {
        "key": "shift+meta+d",
        "command": "autoDocstring.generateDocstring",
        "when": "editorTextFocus"
    },
    {
        "key": "ctrl+shift+2",
        "command": "-autoDocstring.generateDocstring",
        "when": "editorTextFocus"
    },
    {
        "key": "ctrl+meta+u",
        "command": "editor.action.transformToUppercase"
    },
    {
        "key": "ctrl+[IntlBackslash]",
        "command": "-github.copilot.acceptCursorPanelSolution",
        "when": "github.copilot.panelVisible && activeWebviewPanelId == 'GitHub Copilot Suggestions'"
    },
    {
        "key": "ctrl+enter",
        "command": "-github.copilot.generate",
        "when": "editorTextFocus && github.copilot.activated && !commentEditorFocused"
    }
]"}
